const notes = new Map();
let nextId = 1;

export async function listTools() {
  return [
    {
      name: 'note_create',
      description: 'Create a new note',
      inputSchema: {
        type: 'object',
        properties: {
          title: { type: 'string', description: 'Title of the note' },
          body: { type: 'string', description: 'Body of the note' },
        },
        required: ['title', 'body'],
      },
    },
    {
      name: 'note_get',
      description: 'Get a note by ID',
      inputSchema: {
        type: 'object',
        properties: {
          note_id: { type: 'string', description: 'ID of the note' },
        },
        required: ['note_id'],
      },
    },
  ];
}

export async function callTool(name, args) {
  if (name === 'note_create') {
    const { title, body } = args;
    if (typeof title !== 'string' || title.trim() === '') {
      throw new Error('title is required and must be non-empty');
    }
    if (typeof body !== 'string' || body.trim() === '') {
      throw new Error('body is required and must be non-empty');
    }
    const id = `n${nextId++}`;
    notes.set(id, { title: title.trim(), body: body.trim() });
    return {
      content: [
        {
          type: 'text',
          text: `Note created with id: ${id}\nTitle: ${title}\nBody: ${body}`,
        },
      ],
    };
  } else if (name === 'note_get') {
    const { note_id } = args;
    if (typeof note_id !== 'string' || note_id.trim() === '') {
      throw new Error('note_id is required');
    }
    const note = notes.get(note_id);
    if (!note) {
      throw new Error(`Note not found: ${note_id}`);
    }
    return {
      content: [
        {
          type: 'text',
          text: `Title: ${note.title}\nBody: ${note.body}`,
        },
      ],
    };
  } else {
    throw new Error(`Unknown tool: ${name}`);
  }
}
